    #[allow(clippy::too_many_arguments)]
    pub(crate) fn dir_entry_dict(
        &self,
        filename: &Path,
        display_name: &str,
        metadata: Option<&std::fs::Metadata>,
        span: Span,
        long: bool,
        du: bool,
        signals: &Signals,
        use_mime_type: bool,
